        [1462] = {"野兽知识", "收集关于目标野兽的信息。提示信息将显示其伤害、生命值、护甲、任何特殊抗性以及饮食习惯。此外，野兽知识还会揭示该生物是否可以驯服，以及驯服后的生物拥有哪些技能。\n\n效果：揭示知识。", "SpellTranslation"},
        [1463] = {"法力护盾", "吸收一定量伤害，但会消耗法力值。每吸收一点伤害消耗一定量法力值。持续一段时间。\n\n效果：吸收伤害，但会消耗法力值。", "SpellTranslation", "等级 1"},
