        [1499] = {"冰冻陷阱", "放置一个冰霜陷阱，冻结第一个靠近的敌人，使其无法行动，最多持续一段时间。任何伤害都会打破冰冻。陷阱将存在。同一时间内只能激活一个陷阱。", "SpellTranslation", "等级 1"},
