        [27137] = {"圣光闪现", "为友方目标恢复一定量生命值。", "SpellTranslation", "等级 7"},
        [27138] = {"驱邪术", "对亡灵或恶魔目标造成一定量神圣伤害。", "SpellTranslation", "等级 7"},
        [27139] = {"神圣愤怒", "向四周发射神圣能量，对一定范围内的所有亡灵和恶魔目标造成一定量神圣伤害。", "SpellTranslation", "等级 3"},
        [27140] = {"力量祝福", "为友方目标施加祝福，使其攻击强度提高一定量，持续一段时间。每个圣骑士在同一时间内只能在玩家身上激活一种祝福。\n\n效果：攻击强度提高一定量。", "SpellTranslation", "等级 8"},
        [27141] = {"强效力量祝福", "赋予团队或队伍中与目标相同职业的所有成员强效力量祝福，攻击强度提高，持续一段时间。每个圣骑士同一时间只能对一名玩家施放一个祝福。\n\n效果：攻击强度提高一定量。", "SpellTranslation", "等级 3"},
        [27142] = {"智慧祝福", "为友方目标施加祝福，每5秒恢复一定量法力值，持续一段时间。每个圣骑士在同一时间内只能在玩家身上激活一种祝福。\n\n效果：每5秒恢复一定量法力值。", "SpellTranslation", "等级 7"},
        [27143] = {"智慧祝福", "赋予团队或队伍中与目标相同职业的所有成员强效智慧祝福，每5秒恢复一定量法力值，持续一段时间。每个圣骑士同一时间只能对一名玩家施放一个祝福。\n\n效果：每5秒恢复一定量法力值。", "SpellTranslation", "等级 3"},
        [27149] = {"虔诚光环", "使一定范围内的队友和团队成员的护甲值提高一定量。每个圣骑士在同一时间内只能在玩家身上激活一种光环。", "SpellTranslation", "等级 8"},
        [27150] = {"惩罚光环", "对攻击一定范围内的任何小队或团队成员的任何生物造成一定量神圣伤害。每个圣骑士在同一时间内只能在同一目标身上激活一种光环。\n\n效果：对任何攻击你的人造成一定量神圣伤害。", "SpellTranslation", "等级 6"},
        [27151] = {"暗影抗性光环", "使一定范围内的所有小队和团队成员的暗影抗性提高一定量。每个圣骑士在同一时间内只能在玩家身上激活一种光环。", "SpellTranslation", "等级 4"},
        [27152] = {"冰霜抗性光环", "使一定范围内的所有小队和团队成员的冰霜抗性提高一定量。每个圣骑士在同一时间内只能在玩家身上激活一种光环。", "SpellTranslation", "等级 4"},
        [27153] = {"火焰抗性光环", "使一定范围内的所有小队和团队成员的火焰抗性提高一定量。每个圣骑士在同一时间内只能在玩家身上激活一种光环。", "SpellTranslation", "等级 4"},
        [27154] = {"圣疗术", "为友方目标恢复等同于圣骑士生命值上限的生命值，并为其恢复一定量法力值。使用后会耗尽圣骑士所有的法力值。", "SpellTranslation", "等级 4"},
        [27158] = {"十字军圣印", "近战攻击强度提高一定量。近战攻击速度提高一定比例，但伤害降低。", "SpellTranslation", "等级 7"},
        [27169] = {"庇护祝福", "赋予团队或队伍中与目标相同职业的所有成员强效庇护祝福，受到的所有来源伤害最多降低，持续一段时间。此外，当目标格挡一次近战攻击时，攻击者将受到一定量神圣伤害。每个圣骑士同一时间只能对一名玩家施放一个祝福。\n\n效果：受到的伤害最多降低，格挡近战攻击时对攻击者造成一定量神圣伤害。", "SpellTranslation", "等级 2"},
        [27173] = {"奉献", "奉献圣骑士脚下的土地，在一段时间内对进入该区域的敌人造成一定量神圣伤害。\n\n效果：每隔一段时间造成一定量伤害。", "SpellTranslation", "等级 6"},
        [27174] = {"神圣震击", "用神圣能量冲击目标，对敌人造成一定量神圣伤害，或治疗盟友一定量生命值。", "SpellTranslation", "等级 4"},
        [27175] = {"神圣震击", "用神圣能量冲击目标，对敌人造成一定量神圣伤害，或治疗盟友一定量生命值。", "SpellTranslation", "等级 4"},
        [27176] = {"神圣震击", "用神圣能量冲击目标，对敌人造成一定量神圣伤害，或治疗盟友一定量生命值。", "SpellTranslation", "等级 4"},
        [27179] = {"神圣盾", "格挡几率提高一定比例。格挡时对攻击者造成一定量神圣伤害。神圣之盾造成的伤害产生额外35%的威胁值。若干次充能。", "SpellTranslation", "等级 4"},
        [27180] = {"愤怒之锤", "投掷一把锤子打击敌人，造成一定量神圣伤害。只能对生命值低于20%的敌人使用。", "SpellTranslation", "等级 4"},
        [27209] = {"暗影箭", "向敌人发射暗影箭，造成一定量暗影伤害。", "SpellTranslation", "等级 11"},
        [27210] = {"灼热之痛", "对敌方目标造成灼热之痛，造成一定量火焰伤害。产生大量威胁值。", "SpellTranslation", "等级 7"},
        [27211] = {"灵魂之火", "焚烧敌人的灵魂，造成一定量火焰伤害。", "SpellTranslation", "等级 3"},
        [27212] = {"火焰雨", "召唤火焰之雨焚烧区域内的敌人，在一段时间内造成一定量火焰伤害。\n\n效果：每隔一段时间造成一定量火焰伤害。", "SpellTranslation", "等级 5"},
        [27213] = {"地狱烈焰", "对自身和附近所有敌人造成伤害。", "SpellTranslation", "等级 4"},
        [27214] = {"地狱火效果", "", "SpellTranslation", "等级 4"},
        [27215] = {"献祭", "灼烧敌人，造成一定量火焰伤害，并在随后的内额外造成一定量火焰伤害。\n\n效果：每隔一段时间造成一定量火焰伤害。", "SpellTranslation", "等级 9"},
        [27216] = {"腐蚀", "腐蚀目标，在一段时间内造成一定量暗影伤害。\n\n效果：每隔一段时间造成一定量暗影伤害。", "SpellTranslation", "等级 8"},
        [27217] = {"吸取灵魂", "抽取目标的灵魂，在一段时间内造成一定量暗影伤害。如果目标在被抽取期间死亡且能提供经验或荣誉值，则施法者获得一个灵魂碎片。灵魂碎片是施放其他法术所需的。\n\n效果：每隔一段时间造成一定量暗影伤害。", "SpellTranslation", "等级 5"},
        [27218] = {"苦痛诅咒", "使目标陷入痛苦诅咒，在一段时间内造成一定量暗影伤害。伤害开始时较低，随着咒语持续时间的延长而增加。每个术士同一时间只能对同一个目标施加一个诅咒。", "SpellTranslation", "等级 7"},
        [27219] = {"吸取生命", "每隔一段时间将目标的一定量生命值转移给施法者。持续一段时间。\n\n效果：每隔一段时间向施法者吸取一定量", "SpellTranslation", "等级 7"},
        [27220] = {"吸取生命", "每隔一段时间将目标的一定量生命值转移给施法者。持续一段时间。\n\n效果：每隔一段时间向施法者吸取一定量", "SpellTranslation", "等级 8"},
        [27221] = {"吸取法力", "每隔一段时间从目标身上吸取一定量法力值，持续一段时间。\n\n效果：每秒吸取一定量法力值并转移给施法者。", "SpellTranslation", "等级 5"},
        [27222] = {"生命分流", "将一定量生命值转化为一定量法力值。", "SpellTranslation", "等级 7"},
        [27223] = {"死亡缠绕", "使敌方目标因恐惧而逃跑，并造成一定量暗影伤害。施法者将获得相当于伤害量一定比例的生命值。\n\n效果：恐惧中。", "SpellTranslation", "等级 4"},
        [27224] = {"虚弱诅咒", "目标的近战攻击强度降低一定量，持续一段时间。每个术士在同一时间内只能在同一目标身上激活一种诅咒。\n\n效果：近战攻击力降低一定量。", "SpellTranslation", "等级 7"},
        [27226] = {"鲁莽诅咒", "使目标变得鲁莽，近战攻击力提高一定量，但护甲降低一定量，持续一段时间。被诅咒的敌人不会逃跑，并且会免疫恐惧和惊骇效果。每个术士在同一时间内只能对一个目标施加一种诅咒。\n\n效果：近战攻击力提高一定量，护甲降低一定量。目标不会逃跑，并免疫恐惧和惊骇效果。", "SpellTranslation", "等级 5"},
        [27228] = {"元素诅咒", "诅咒目标，持续一段时间，使其奥术、火焰、冰霜和暗影抗性降低，并使其受到的奥术、火焰、冰霜和暗影伤害提高一定比例。每个术士同一时间只能对同一个目标施加一个诅咒。\n\n效果：奥术、火焰、冰霜和暗影抗性降低。受到的奥术、火焰、冰霜和暗影伤害提高一定比例。", "SpellTranslation", "等级 4"},
        [27230] = {"制造治疗石", "制造一颗大师级治疗石，可用于立即恢复一定量生命值。\n\n制造出的物品如果在离线状态下超过15分钟就会消失。", "SpellTranslation", "等级 6"},
        [27238] = {"制造灵魂石", "制造一个大师级灵魂石。灵魂石可用于储存一个目标的灵魂。如果目标在灵魂被储存期间死亡，他们将能够以一定量生命值和一定量法力值复活。\n\n制造出的物品如果在离线状态下超过15分钟就会消失。", "SpellTranslation", "等级 6"},
        [27241] = {"咕唧", "右键点击召唤或解散小鱼人格奇。", "SpellTranslation"},
        [27243] = {"腐蚀之种", "", "SpellTranslation", "等级 1"},
        [27250] = {"制造火焰石", "制造一块可以装备的大师火焰石。装备后，为你的主手武器附魔火焰，使每次攻击都有一定几率造成一定量额外的火焰伤害。此外，装备大师火焰石还能使你的火焰法术造成的伤害提高一定量。\n\n制造出的物品如果在离线状态下超过15分钟就会消失。", "SpellTranslation", "等级 5"},
