        [27269] = {"火焰之盾", "在目标周围形成一道火焰护盾，使其火焰抗性提高，并使对目标的每次攻击对攻击者造成一定量火焰伤害。持续一段时间。施法者无法对自己施放火焰护盾。\n\n效果：火焰抗性提高，被击中时对攻击者造成一定量火焰伤害。", "SpellTranslation", "等级 6"},
        [27270] = {"折磨", "嘲讽生物，增加其攻击虚空行者的几率。比受难（等级6）更有效。", "SpellTranslation", "等级 7"},
        [27271] = {"Suffering", "嘲讽一定范围内的所有敌人，增加其攻击虚空行者的几率，并使其命中几率降低一定比例，持续一段时间。比折磨（等级4）更有效。\n\n效果：命中几率降低一定比例。", "SpellTranslation", "等级 5"},
        [27272] = {"Consume Shadows", "虚空行者吞噬周围的阴影以增强体质，在一段时间内恢复一定量生命值，并大幅提高一定范围内附近所有友方目标的潜行侦测能力。无法在战斗中使用。\n\n效果：每隔一段时间治疗一定量伤害，并大幅提高一定范围内所有友方目标的潜行侦测能力。", "SpellTranslation", "等级 7"},
        [27273] = {"牺牲", "牺牲虚空行者，为它的主人提供一个可以吸收一定量伤害的护盾，持续一段时间。只要护盾存在，施法就不会因为受到伤害而被打断。\n\n效果：吸收所有伤害。", "SpellTranslation", "等级 7"},
        [27274] = {"剧痛鞭笞", "一记瞬间发动的鞭笞攻击，对目标造成一定量暗影伤害。", "SpellTranslation", "等级 7"},
        [27275] = {"安抚之吻", "安抚目标，增加其攻击其他目标的几率，并使其近战攻击速度降低一定比例，持续一段时间。比安抚之吻（等级4）更有效。\n\n效果：近战攻击速度降低一定比例。", "SpellTranslation", "等级 5"},
        [27276] = {"吞噬魔法", "从友方目标身上驱散若干个有害魔法效果，或从敌方目标身上驱散若干个有利魔法效果。如果吞噬了一个效果，地狱猎犬将获得一定量治疗。", "SpellTranslation", "等级 5"},
        [27277] = {"吞噬魔法", "从友方目标身上驱散若干个有害魔法效果，或从敌方目标身上驱散若干个有利魔法效果。如果吞噬了一个效果，地狱猎犬将获得一定量治疗。", "SpellTranslation", "等级 6"},
