        [31892] = {"悔罪圣印", "所有的近战攻击都会造成额外的神圣伤害，数值相当于普通武器伤害的一定比例，但圣骑士也会损失生命值，数值相当于造成的总伤害的一定比例。\n\n释放这种圣印的能量将审判敌人，立即造成一定量神圣伤害，代价是损失生命值，数值相当于造成的伤害的33%。\n\n效果：近战攻击以消耗生命值为代价造成额外神圣伤害。", "SpellTranslation", "等级 1"},
        [31895] = {"正义圣印", "使圣骑士获得公正之心的加持，持续一段时间，使每次近战攻击都有一定几率使其昏迷。圣骑士在同一时间内只能激活一种圣印。\n\n释放这种圣印的能量将审判敌人，持续一段时间，使其无法逃跑并限制其移动速度。你的近战攻击会刷新该法术的持续时间。每个圣骑士在同一时间内只能激活一个审判效果。\n\n效果：近战攻击有一定几率使目标昏迷。", "SpellTranslation", "等级 2"},
        [31898] = {"悔罪审判", "释放此圣印的能量将审判一个敌人，立即造成一定量神圣伤害，代价是损失相当于伤害量33%的生命值。", "SpellTranslation", "等级 1"},
