        [47846] = {"暗影之怒", "释放暗影之怒，对一定范围内的所有敌人造成一定量暗影伤害并使其昏迷，持续一段时间。\n\n效果：昏迷。", "SpellTranslation", "等级 4"},
        [47847] = {"暗影之怒", "释放暗影之怒，对一定范围内的所有敌人造成一定量暗影伤害并使其昏迷，持续一段时间。\n\n效果：昏迷。", "SpellTranslation", "等级 5"},
        [47855] = {"吸取灵魂", "吸取目标的灵魂，在一段时间内造成一定量暗影伤害。如果目标的生命值等于或低于25%，吸取灵魂会造成四倍于平常的伤害。如果目标在被吸取灵魂期间死亡并产生经验或荣誉，施法者将获得一个灵魂碎片。吸取灵魂每次造成伤害时，都有一定几率产生一个灵魂碎片。其他法术需要消耗灵魂碎片。\n\n效果：每隔一段时间造成一定量暗影伤害。", "SpellTranslation", "等级 6"},
        [47856] = {"生命通道", "只要施法者保持引导，每秒将一定量生命值转移给其宠物。持续一段时间。\n\n效果：正在转移生命。", "SpellTranslation", "等级 9"},
        [47857] = {"吸取生命", "每隔一段时间将目标的一定量生命值转移给施法者。持续一段时间。\n\n效果：每隔一段时间向施法者吸取一定量", "SpellTranslation", "等级 9"},
        [47859] = {"死亡缠绕", "使敌方目标因恐惧而逃跑，并造成一定量暗影伤害。施法者将获得相当于伤害量一定比例的生命值。\n\n效果：恐惧中。", "SpellTranslation", "等级 5"},
        [47860] = {"死亡缠绕", "使敌方目标因恐惧而逃跑，并造成一定量暗影伤害。施法者将获得相当于伤害量一定比例的生命值。\n\n效果：恐惧中。", "SpellTranslation", "等级 6"},
        [47863] = {"苦痛诅咒", "使目标陷入痛苦诅咒，在一段时间内造成一定量暗影伤害。伤害开始时较低，随着咒语持续时间的延长而增加。每个术士同一时间只能对同一个目标施加一个诅咒。", "SpellTranslation", "等级 8"},
        [47864] = {"苦痛诅咒", "使目标陷入痛苦诅咒，在一段时间内造成一定量暗影伤害。伤害开始时较低，随着咒语持续时间的延长而增加。每个术士同一时间只能对同一个目标施加一个诅咒。", "SpellTranslation", "等级 9"},
        [47865] = {"元素诅咒", "诅咒目标，持续一段时间，使其奥术、火焰、冰霜、自然和暗影抗性降低，并使其受到的魔法伤害提高一定比例。同一时间术士只能在一个目标身上激活一种诅咒。\n\n效果：奥术、火焰、冰霜、自然和暗影抗性降低。受到的魔法伤害提高一定比例。", "SpellTranslation", "等级 5"},
        [47867] = {"厄运诅咒", "使目标遭受厄运，在后造成一定量暗影伤害。如果目标死于该伤害，则有几率召唤出一名末日守卫。无法对玩家施放。", "SpellTranslation", "等级 3"},
        [47871] = {"制造治疗石", "制造一块恶魔治疗石，可以立即恢复一定量生命值。\n\n制造出的物品如果在离线状态下超过15分钟就会消失。", "SpellTranslation", "等级 7"},
        [47878] = {"制造治疗石", "制造一块魔能治疗石，可以立即恢复一定量生命值。\n\n制造出的物品如果在离线状态下超过15分钟就会消失。", "SpellTranslation", "等级 8"},
        [47884] = {"制造灵魂石", "制造一个恶魔灵魂石。灵魂石可以用来储存一个目标的灵魂。如果目标在灵魂储存期间死亡，他将能够以一定量生命值和一定量法力值复活。\n\n制造出的物品如果在离线状态下超过15分钟就会消失。", "SpellTranslation", "等级 7"},
        [47886] = {"制造法术石", "施加在武器上时，使周期性法术造成的伤害提高一定比例，法术急速等级提高。持续1小时。", "SpellTranslation", "等级 5"},
        [47888] = {"制造法术石", "施加在武器上时，使周期性法术造成的伤害提高一定比例，法术急速等级提高。持续1小时。", "SpellTranslation", "等级 6"},
