        [47988] = {"Consume Shadows", "虚空行者吞噬周围的阴影以增强体质，在一段时间内恢复一定量生命值，并大幅提高一定范围内附近所有友方目标的潜行侦测能力。无法在战斗中使用。\n\n效果：每隔一段时间治疗一定量伤害，并大幅提高一定范围内所有友方目标的潜行侦测能力。", "SpellTranslation", "等级 9"},
