        [48938] = {"智慧祝福", "赋予团队或队伍中与目标相同职业的所有成员强效智慧祝福，每5秒恢复一定量法力值，持续一段时间。每个圣骑士同一时间只能对一名玩家施放一个祝福。\n\n效果：每5秒恢复一定量法力值。", "SpellTranslation", "等级 5"},
        [48941] = {"虔诚光环", "使一定范围内的队友和团队成员的护甲值提高一定量。每个圣骑士在同一时间内只能在玩家身上激活一种光环。", "SpellTranslation", "等级 9"},
        [48942] = {"虔诚光环", "使一定范围内的队友和团队成员的护甲值提高一定量。每个圣骑士在同一时间内只能在玩家身上激活一种光环。", "SpellTranslation", "等级 10"},
        [48943] = {"暗影抗性光环", "使一定范围内的所有小队和团队成员的暗影抗性提高一定量。每个圣骑士在同一时间内只能在玩家身上激活一种光环。", "SpellTranslation", "等级 5"},
        [48945] = {"冰霜抗性光环", "使一定范围内的所有小队和团队成员的冰霜抗性提高一定量。每个圣骑士在同一时间内只能在玩家身上激活一种光环。", "SpellTranslation", "等级 5"},
        [48947] = {"火焰抗性光环", "使一定范围内的所有小队和团队成员的火焰抗性提高一定量。每个圣骑士在同一时间内只能在玩家身上激活一种光环。", "SpellTranslation", "等级 5"},
