        [48950] = {"救赎", "使死亡的玩家复活，并使其拥有一定量生命值和一定量法力值。无法在战斗中施放。", "SpellTranslation", "等级 7"},
        [48951] = {"神圣盾", "格挡几率提高一定比例。格挡时对攻击者造成一定量神圣伤害。若干次充能。", "SpellTranslation", "等级 5"},
