        [48988] = {"血腥复仇", "在你通过武器攻击、法术或技能造成暴击后，使你造成的物理伤害提高一定比例，持续一段时间。此效果最多可叠加若干次。", "SpellTranslation", "等级 1"},
        [48989] = {"治疗宠物", "在一段时间内为你的宠物恢复一定量生命值。\n\n效果：每隔一段时间恢复一定量生命值。", "SpellTranslation", "等级 9"},
        [48990] = {"治疗宠物", "在一段时间内为你的宠物恢复一定量生命值。\n\n效果：每隔一段时间恢复一定量生命值。", "SpellTranslation", "等级 10"},
