        [48998] = {"Counterattack", "在招架对手攻击后激活的一次打击。该攻击造成一定量伤害，并使目标定身。反击无法被格挡、躲闪或招架。", "SpellTranslation", "等级 5"},
        [48999] = {"Counterattack", "在招架对手攻击后激活的一次打击。该攻击造成一定量伤害，并使目标定身。反击无法被格挡、躲闪或招架。", "SpellTranslation", "等级 6"},
        [49000] = {"毒蛇钉刺", "钉刺目标，在一段时间内造成一定量自然伤害。每个猎人在同一时间内只能在同一目标身上激活一种钉刺。\n\n效果：每隔一段时间造成一定量自然伤害。", "SpellTranslation", "等级 11"},
        [49001] = {"毒蛇钉刺", "钉刺目标，在一段时间内造成一定量自然伤害。每个猎人在同一时间内只能在同一目标身上激活一种钉刺。\n\n效果：每隔一段时间造成一定量自然伤害。", "SpellTranslation", "等级 12"},
        [49004] = {"血之气息", "你在躲闪、招架或受到直接伤害后有一定比例的几率获得血之气息效果，使你的下一次近战攻击产生10点符文能量。", "SpellTranslation", "等级 1"},
        [49005] = {"血之印记", "在一个敌人身上施加鲜血印记。每当被标记的敌人对造成伤害时，该目标都会恢复生命值，数值相当于其最大生命值的一定比例。持续一段时间或生效若干次。\n\n效果：此目标的命中恢复一定比例生命值。", "SpellTranslation"},
