        [49009] = {"翼龙钉刺", "使目标沉睡的蛰刺。任何伤害都会取消该效果。当目标醒来时，蛰刺会在一段时间内造成一定量自然伤害。每个猎人同一时间内只能在目标身上激活一种蛰刺效果。\n\n效果：每隔一段时间造成一定量自然伤害。", "SpellTranslation", "等级 5"},
        [49010] = {"翼龙钉刺", "使目标沉睡的蛰刺。任何伤害都会取消该效果。当目标醒来时，蛰刺会在一段时间内造成一定量自然伤害。每个猎人同一时间内只能在目标身上激活一种蛰刺效果。\n\n效果：每隔一段时间造成一定量自然伤害。", "SpellTranslation", "等级 6"},
        [49011] = {"翼龙钉刺", "射出一支带刺的箭矢，使目标沉睡。任何伤害都会取消该效果。当目标醒来时，毒刺会在一段时间内造成一定量自然伤害。每个猎人同一时间内只能对一个目标施放一种毒刺效果。\n\n效果：正在休眠。", "SpellTranslation", "等级 5"},
        [49012] = {"翼龙钉刺", "射出一支带刺的箭矢，使目标沉睡。任何伤害都会取消该效果。当目标醒来时，毒刺会在一段时间内造成一定量自然伤害。每个猎人同一时间内只能对一个目标施放一种毒刺效果。\n\n效果：正在休眠。", "SpellTranslation", "等级 6"},
