        [49016] = {"狂暴", "使一个友方单位进入杀戮狂乱，持续一段时间。目标会进入激怒状态，使其造成的物理伤害提高一定比例，但每秒会损失相当于其最大生命值一定比例的生命值。\n\n效果：激怒。\n物理伤害提高一定比例。\n每秒损失最大生命值的一定比例。", "SpellTranslation"},
