        [49149] = {"墓穴之寒", "你的冰链术、凛冽寒风、冰冷触摸和湮灭会产生额外的2.5点符文能量。", "SpellTranslation", "等级 1"},
        [49158] = {"尸体爆炸", "引爆一具尸体，对一定范围内的所有敌人造成一定量暗影伤害。如果目标不是尸体，则会使用附近的一具尸体。不会影响机械体或元素生物的尸体。", "SpellTranslation", "等级 1"},
