        [49186] = {"冰冷恐惧铠", "使近战攻击命中你的几率降低一定比例。", "SpellTranslation", "等级 1"},
        [49188] = {"白霜", "使你的冰冷触摸和湮没暴击几率提高一定比例，并且施放湮没有一定比例的几率重置凛风冲击的冷却时间，并使你的下一个凛风冲击不消耗符文。", "SpellTranslation", "等级 1"},
        [49189] = {"亡灵天灾之意志", "使你生命值降至一定比例以下的伤害或在你生命值处于一定比例以下时受到的伤害降低一定比例。", "SpellTranslation", "等级 1"},
        [49193] = {"复仇角斗士的虚空幼龙", "移动速度取决于你的骑术。", "SpellTranslation"},
        [49194] = {"被烧毁的", "使受到你缠绕攻击的目标被邪恶的昆虫包围，在一段时间内受到相当于缠绕伤害一定比例的伤害，并防止目标身上的任何疾病效果被驱散。\n\n效果：正在受到邪恶虫群的伤害。疾病无法被驱散。", "SpellTranslation"},
        [49200] = {"适应", "当你被法术击中时，有一定比例的几率提高你对该系魔法的抗性，持续18秒。最多可叠加3层。", "SpellTranslation", "等级 1"},
        [49202] = {"冻原潜行者", "你的法术和技能对感染冰霜热疫的目标造成的伤害提高一定比例。同时使你的精准提高。", "SpellTranslation", "等级 1"},
        [49203] = {"饥饿之寒", "清除死亡骑士周围地面上的所有热量。一定范围内的敌人将被困在冰中，在一段时间内无法进行任何动作，并感染霜疫。敌人被视为处于冻结状态，但除了疾病以外的任何伤害都会打破冰冻。", "SpellTranslation", "等级 1"},
