        [50305] = {"剥皮", "剥取野兽毛皮的高级技巧，用于制皮。使你的剥皮技能上限达到450点。需要剥皮小刀。", "SpellTranslation", "宗师"},
        [50310] = {"采矿", "你是一名宗师级采矿者。使你的采矿技能上限达到450点。", "SpellTranslation", "宗师"},
        [50318] = {"宁静之尘", "飞蛾振翅洒出一团尘粉，使其攻击强度提高一定量，并在一段时间内恢复一定量生命值。\n\n效果：攻击强度提高。\n每隔一段时间治疗一定量伤害。", "SpellTranslation", "等级 1"},
        [50322] = {"被烧毁的", "激活后，此技能暂时为你提供当前最大生命值的一定比例，持续一段时间。只能在熊形态、豹形态或巨熊形态下使用。效果结束后，增加的生命值会消失。\n\n效果：生命值提高。", "SpellTranslation"},
        [50334] = {"狂暴", "激活后，此技能使你的裂伤（熊）技能可以同时攻击最多若干个目标且没有冷却时间，并使你所有豹形态技能的能量消耗降低一定比例，持续一段时间。狂暴激活期间无法使用猛虎之怒。\n\n清除所有恐惧效果，并在持续时间内免疫恐惧。\n\n效果：免疫恐惧效果。", "SpellTranslation"},
        [50365] = {"强化鲜血姿态", "在冰霜灵气或邪恶灵气下，你保留鲜血灵气的一定比例治疗效果，并在鲜血灵气下使你受到的治疗效果提高一定比例。", "SpellTranslation", "等级 1"},
        [50371] = {"强化鲜血姿态", "在冰霜灵气或邪恶灵气下，你保留鲜血灵气的一定比例治疗效果，并在鲜血灵气下使你受到的治疗效果提高一定比例。", "SpellTranslation", "等级 2"},
        [50384] = {"强化冰霜姿态", "在鲜血灵气或邪恶灵气下，你保留冰霜灵气的一定比例耐力加成，并在冰霜灵气下使你受到的伤害额外降低一定比例。", "SpellTranslation", "等级 1"},
        [50385] = {"强化冰霜姿态", "在鲜血灵气或邪恶灵气下，你保留冰霜灵气的一定比例耐力加成，并在冰霜灵气下使你受到的伤害额外降低一定比例。", "SpellTranslation", "等级 2"},
        [50391] = {"强化邪恶姿态", "在鲜血灵气或冰霜灵气下，你保留邪恶灵气提高一定比例移动速度的效果，并在邪恶灵气下使你的符文冷却完成速度提高一定比例。", "SpellTranslation", "等级 1"},
        [50392] = {"强化邪恶姿态", "在鲜血灵气或冰霜灵气下，你保留邪恶灵气提高一定比例移动速度的效果，并在邪恶灵气下使你的符文冷却完成速度提高一定比例。", "SpellTranslation", "等级 2"},
        [50444] = {"尸体爆炸", "使一具尸体爆炸，对一定范围内的所有敌人造成一定量暗影伤害。如果目标不是尸体，则会寻找附近的尸体。对机械或元素生物的尸体无效。", "SpellTranslation"},
        [50447] = {"血腥复仇", "当你通过武器挥击、法术或技能造成暴击后，在一段时间内使你造成的物理伤害提高一定比例。该效果最多可叠加若干层。", "SpellTranslation"},
