        [50464] = {"星涌术", "为一名友方目标恢复一定量生命值。如果目标身上已经拥有回春术、愈合、生命绽放或野性成长效果，则治疗效果额外提高20%。", "SpellTranslation", "等级 1"},
        [50511] = {"虚弱诅咒", "目标的近战攻击强度降低一定量，护甲降低一定比例，持续一段时间。每个术士同一时间只能在一个目标身上激活一种诅咒。\n\n效果：近战攻击强度降低，护甲降低一定比例。", "SpellTranslation", "等级 9"},
