        [51490] = {"雷霆风暴", "你召下一道闪电，为自己注入能量并伤害一定范围内附近的敌人。为你恢复一定比例的法力值，并对附近所有敌人造成一定量自然伤害，将其击退20码。该法术可在昏迷状态下使用。", "SpellTranslation", "等级 1"},
