        [53323] = {"碎剑符文", "为你的双手符文武器附加一个符文，使招架几率提高4%，且缴械效果的持续时间缩短一定比例。修改符文武器需要前往黑锋要塞的符文熔炉。", "SpellTranslation"},
        [53331] = {"巫妖克星符文", "为你的符文武器附加一个符文，使你的武器攻击额外造成2%的火焰伤害，对亡灵目标的额外伤害则为4%。修改符文武器需要前往黑锋要塞的符文熔炉。", "SpellTranslation"},
        [53338] = {"猎人印记", "在目标身上施加猎人印记，使所有攻击者对该目标的远程攻击强度提高。此外，无论目标是处于潜行还是隐形状态，施放此技能的猎人都能看到它。目标也会出现在缩略地图上。持续一段时间。\n\n效果：所有攻击者对此目标获得一定量远程攻击强度。", "SpellTranslation", "等级 5"},
