        [53342] = {"碎咒符文", "为你的双手符文武器附加一个符文，使你偏转所有法术伤害的几率提高一定比例，且沉默效果的持续时间缩短一定比例。修改符文武器需要前往黑锋要塞的符文熔炉。", "SpellTranslation"},
        [53343] = {"锋冰符文", "为你的武器附加一个符文，使你的武器攻击额外造成2%的冰霜伤害，并提高敌人对你的冰霜攻击的易伤几率。修改符文武器需要前往黑锋要塞的符文熔炉。", "SpellTranslation"},
        [53344] = {"堕落十字军符文", "为你的符文武器附加一个符文，使其有一定几率为你恢复一定比例的生命值，并使你的总力量提高一定比例，持续一段时间。修改符文武器需要前往黑锋要塞的符文熔炉。", "SpellTranslation"},
        [53351] = {"杀戮射击", "你试图终结受伤的目标，发射一次远程攻击，造成一定比例的武器伤害外加一定量额外伤害。杀戮射击只能对生命值为20%或以下的敌人使用。", "SpellTranslation", "等级 1"},
