        [54037] = {"强化地狱猎犬", "你的地狱猎犬在使用暗影咬合技能击中目标时会恢复4%的最大法力值，且该技能的冷却时间缩短数秒。此外，地狱猎犬的邪能智力效果提高一定比例。", "SpellTranslation", "等级 1"},
        [54038] = {"强化地狱猎犬", "你的地狱猎犬在使用暗影咬合技能击中目标时会恢复8%的最大法力值，且该技能的冷却时间缩短数秒。此外，地狱猎犬的邪能智力效果提高一定比例。", "SpellTranslation", "等级 2"},
        [54043] = {"惩罚光环", "对击中一定范围内任何小队或团队成员的敌人造成一定量神圣伤害。每个玩家同一时间只能获得一名圣骑士提供的一种光环效果。\n\n效果：对任何攻击你的人造成一定量神圣伤害。", "SpellTranslation", "等级 7"},
        [54044] = {"食腐", "你的宠物可以通过吞噬尸体来恢复生命值和心情。对元素或机械生物的残骸无效。", "SpellTranslation"},
        [54049] = {"暗影撕咬", "撕咬敌人，造成一定量暗影伤害，并且目标身上的每个由你施加的持续伤害效果都会使该伤害额外提高一定比例。", "SpellTranslation", "等级 1"},
        [54050] = {"暗影撕咬", "撕咬敌人，造成一定量暗影伤害，并且目标身上的每个由你施加的持续伤害效果都会使该伤害额外提高一定比例。", "SpellTranslation", "等级 2"},
        [54051] = {"暗影撕咬", "撕咬敌人，造成一定量暗影伤害，并且目标身上的每个由你施加的持续伤害效果都会使该伤害额外提高一定比例。", "SpellTranslation", "等级 3"},
        [54052] = {"暗影撕咬", "撕咬敌人，造成一定量暗影伤害，并且目标身上的每个由你施加的持续伤害效果都会使该伤害额外提高一定比例。", "SpellTranslation", "等级 4"},
        [54053] = {"暗影撕咬", "撕咬敌人，造成一定量暗影伤害，并且目标身上的每个由你施加的持续伤害效果都会使该伤害额外提高一定比例。", "SpellTranslation", "等级 5"},
        [54117] = {"强化灵魂汲取", "你的灵魂汲取效果还会为你和你召唤的恶魔恢复相当于最大法力值一定比例的法力值，并有一定比例的几率使最多10名小队或团队成员获得法力恢复效果，每5秒恢复相当于最大法力值1%的法力，持续一段时间。", "SpellTranslation", "等级 1"},
        [54118] = {"强化灵魂汲取", "你的灵魂汲取效果还会为你和你召唤的恶魔恢复相当于最大法力值一定比例的法力值，并有一定比例的几率使最多10名小队或团队成员获得法力恢复效果，每5秒恢复相当于最大法力值1%的法力，持续一段时间。", "SpellTranslation", "等级 2"},
        [54149] = {"圣光灌注", "你的神圣震击造成的暴击使你的下一个圣光闪现的施法时间缩短.1秒，或使你的下一个圣光术的暴击几率提高一定比例。\n\n效果：你的下一次圣光闪现的施法时间缩短.1秒，或下一次圣光术的暴击几率提高一定比例。", "SpellTranslation", "等级 2"},
