        [55459] = {"治疗链", "为友方目标恢复一定量生命值，然后跳跃治疗附近的其他目标。如果对小队成员施放，治疗效果只会跳向其他小队成员。每次跳跃都会使治疗效果降低40%。总共治疗若干个目标。", "SpellTranslation", "等级 7"},
        [55531] = {"机械摩托", "驾驶一辆帅气的机械路霸。这可是非常快的交通工具。这种坐骑的移动速度取决于你的骑术等级。\n\n效果：移动速度取决于你的骑术。", "SpellTranslation"},
