        [55610] = {"强化冰爪", "使一定范围内所有小队和团队成员的近战急速提高一定比例，并使你额外获得一定比例的急速加成。\n\n效果：近战急速提高一定比例。", "SpellTranslation"},
        [55620] = {"亡者之夜", "使起尸术的冷却时间缩短数秒，亡者大军的冷却时间缩短分钟。此外，使你的宠物受到生物范围伤害攻击的伤害降低一定比例。", "SpellTranslation", "等级 1"},
