        [57933] = {"嫁祸诀窍", "嫁祸诀窍的盗贼技能效果。\n\n效果：All damage caused increased 一定量。All threat transferred from rogue to target.", "SpellTranslation"},
        [57934] = {"嫁祸诀窍", "嫁祸诀窍的盗贼技能效果。\n\n效果：The threat caused by your next damaging attack and all actions taken for d afterwards will be transferred to the target. In addition, all damage caused by the target is increased by s1% during this time.", "SpellTranslation"},
