        [57992] = {"毒伤", "终结技，消耗目标身上的致命药膏层数并立即造成毒药伤害。每个连击点消耗一层，消耗层数越多伤害越高，并短暂提高你施加药膏的几率：\n1层：约75点毒药伤害，另受攻击强度加成\n2层：约150点毒药伤害，另受攻击强度加成\n3层：约225点毒药伤害，另受攻击强度加成\n4层：约300点毒药伤害，另受攻击强度加成\n5层：约375点毒药伤害，另受攻击强度加成\n\n效果：Chance to apply Deadly Poison increased by % and frequency of applying Instant Poison increased 一定量。", "SpellTranslation", "等级 3"},
        [57993] = {"毒伤", "终结技，消耗目标身上的致命药膏层数并立即造成毒药伤害。每个连击点消耗一层，消耗层数越多伤害越高，并短暂提高你施加药膏的几率：\n1层：约75点毒药伤害，另受攻击强度加成\n2层：约150点毒药伤害，另受攻击强度加成\n3层：约225点毒药伤害，另受攻击强度加成\n4层：约300点毒药伤害，另受攻击强度加成\n5层：约375点毒药伤害，另受攻击强度加成\n\n效果：Chance to apply Deadly Poison increased by % and frequency of applying Instant Poison increased 一定量。", "SpellTranslation", "等级 4"},
