        [84630] = {"安抚元素", "安抚目标元素生物，使其攻击你的范围缩小一定范围。仅对70级或以下的元素生物有效。持续一段时间。\n\n效果：缩小了目标会发动攻击的距离。", "SpellTranslation", "等级 3"},
        [84642] = {"滚滚惊雷", "如果你拥有激活的闪电之盾，你的闪电箭和链状闪电爆击后有一定比例的几率使闪电之盾增加一次层数，最多可达9层。当你达到9层后，任何增加层数的尝试都会改为向目标发射一个闪电球。\n\n当你拥有超过3层闪电之盾时，你的地震术将在2秒后消耗最多1层额外的闪电之盾，并将其射向目标。", "SpellTranslation"},
        [84644] = {"滚滚惊雷", "如果你拥有激活的闪电之盾，你的闪电箭和链状闪电爆击后有一定比例的几率使闪电之盾增加一次层数，最多可达9层。当你达到9层后，任何增加层数的尝试都会改为向目标发射一个闪电球。\n\n当你拥有超过3层闪电之盾时，你的地震术将每2秒消耗最多2层额外的闪电之盾（持续最多4秒），并将其射向目标。", "SpellTranslation"},
        [84646] = {"滚滚惊雷", "如果你拥有激活的闪电之盾，你的闪电箭和链状闪电爆击后有一定比例的几率使闪电之盾增加一次层数，最多可达9层。当你达到9层后，任何增加层数的尝试都会改为向目标发射一个闪电球。\n\n当你拥有超过3层闪电之盾时，你的地震术将每2秒消耗最多3层额外的闪电之盾（持续最多6秒），并将其射向目标。", "SpellTranslation"},
        [84648] = {"奥术冲击", "用能量冲击目标，造成一定量奥术伤害。每次施放奥术冲击，施法时间都会缩短，但法力消耗会提高。该效果最多可叠加若干层，持续一段时间。", "SpellTranslation", "等级 1"},
