        [84667] = {"魔法武器", "制造一把耐久度为50的匕首，任何可以使用此类武器的人都可以装备。匕首造成的伤害取决于法师的等级。\n\n制造出的物品在离线超过15分钟后会消失。", "SpellTranslation", "等级 1"},
        [84668] = {"魔法武器", "制造一把耐久度为50的短剑，任何可以使用此类武器的人都可以装备。短剑造成的伤害取决于法师的等级。\n\n制造出的物品在离线超过15分钟后会消失。", "SpellTranslation", "等级 2"},
        [84669] = {"魔法武器", "制造一把耐久度为50的大剑，任何可以使用此类武器的人都可以装备。大剑造成的伤害取决于法师的等级。\n\n制造出的物品在离线超过15分钟后会消失。", "SpellTranslation", "等级 3"},
