        [84673] = {"魔法武器", "制造一把耐久度为50的战斧，任何可以使用此类武器的人都可以装备。战斧造成的伤害取决于法师的等级。\n\n制造出的物品在离线超过15分钟后会消失。", "SpellTranslation", "等级 7"},
        [84701] = {"恶魔赋能", "被赋予力量。", "SpellTranslation"},
        [84704] = {"灵魂契约", "与一名小队或团队成员的灵魂订立契约。如果目标在契约期间死亡，你将获得1块灵魂碎片，且你的法术伤害提高一定量，持续一段时间。\n\n效果：与附近的术士灵魂绑定。", "SpellTranslation"},
        [84708] = {"恶魔之门", "撕开一道通往虚空的传送门，持续一段时间，周期性地召唤出一个受你控制的恶魔。这些恶魔不会替换你当前激活的恶魔。传送门召唤出的最后一个恶魔总是恶魔卫士，它在出现时会使你的当前目标昏迷4秒。远离传送门超过45码会导致其关闭。", "SpellTranslation"},
        [84722] = {"强化暗影撕咬", "你的地狱猎犬每次使用暗影咬合击中目标时，都会恢复5%的最大法力值。", "SpellTranslation", "等级 1"},
        [84723] = {"强化暗影撕咬", "你的地狱猎犬每次使用暗影咬合击中目标时，都会恢复10%的最大法力值。", "SpellTranslation", "等级 2"},
        [84724] = {"暗影之怒", "释放暗影之怒，对一定范围内的所有敌人造成一定量暗影伤害并使其昏迷，持续一段时间。\n\n效果：昏迷。", "SpellTranslation", "等级 2"},
        [84725] = {"暗影之怒", "释放暗影之怒，对一定范围内的所有敌人造成一定量暗影伤害并使其昏迷，持续一段时间。\n\n效果：昏迷。", "SpellTranslation", "等级 3"},
        [84728] = {"献祭光环", "地狱火周围的敌人每隔一段时间受到一定量火焰伤害。\n\n效果：每隔一段时间对附近的敌人造成一定量火焰伤害。", "SpellTranslation"},
        [84730] = {"野性攻击", "所有可装备的武器都将根据武器的秒伤获得额外的野性攻击强度。只有德鲁伊可以看到此属性。", "SpellTranslation", "被动"},
